<?php
namespace App\Http\Controllers;
use App\Models\{Event,Category,Venue}; use Illuminate\Http\Request;
class CatalogController extends Controller { public function search(Request $r){$q=Event::with('category')->where('status','published');if($r->filled('q'))$q->where(fn($x)=>$x->where('title','like','%'.$r->q.'%')->orWhere('summary','like','%'.$r->q.'%'));if($r->filled('type'))$q->where('type',$r->string('type'));if($r->filled('category'))$q->where('category_id',$r->integer('category'));if($r->filled('city'))$q->whereHas('shows.venue',fn($x)=>$x->where('city',$r->string('city')));if($r->filled('date'))$q->whereHas('shows',fn($x)=>$x->whereDate('starts_at',$r->date('date')));return view('catalog.search',['events'=>$q->latest()->paginate(18)->withQueryString(),'categories'=>Category::where('type','event')->get(),'cities'=>Venue::query()->distinct()->orderBy('city')->pluck('city')]);} }
